        self.calculator = FactorialCalculator()

    def perform_calculation(self, n_val):
        input_num = InputNumber(n_val)
        return self.calculator.compute(input_num.number)

def calculate_factorial(n):
    manager = CalculationManager()
    return manager.perform_calculation(n)

