class BasicValidationResult:
    def __init__(self, is_valid, message=""):
        self.is_valid = is_valid
        self.message = message

class CharacterPresenceChecker:
    def check(self, text, char):
        return char in text

class CharacterOrderVerifier:
    def verify(self, text, char1, char2):
        try:
            return text.index(char1) < text.index(char2)
        except ValueError:
            return False

class ValidationEngine:
    def __init__(self):
        self.presence_checker = CharacterPresenceChecker()
        self.order_verifier = CharacterOrderVerifier()

    def perform_validation(self, email_object):
        if not self.presence_checker.check(email_object.value, '@'):
            return BasicValidationResult(False, "Missing '@'")
        if not self.presence_checker.check(email_object.value, '.'):
            return BasicValidationResult(False, "Missing '.'")
        if not self.order_verifier.verify(email_object.value, '@', '.'):
            return BasicValidationResult(False, "'@' must appear before '.'")
        return BasicValidationResult(True, "Email is valid")

def validate_email(email):
    email_string_instance = EmailString(email)
    validation_engine_instance = ValidationEngine()
    result_object = validation_engine_instance.perform_validation(email_string_instance)
    return result_object.is_valid

