        self.key = key_val
        self.value = value_val

    def to_tuple(self):
        return (self.key, self.value)

class ValueComparator:
    def __init__(self, item_val):
        self.item = item_val

    def get_value(self):
        return self.item.value

class DictionaryProcessor:
    def __init__(self, input_dict):
        self.original_dict = input_dict

    def process(self):
        item_list = [OrderItem(k, v) for k, v in self.original_dict.items()]
        return item_list

class SortingEngine:
    def sort_items(self, items):
        return sorted(items, key=lambda item: ValueComparator(item).get_value())

