    dict_processor = DictionaryProcessor(d)
    processed_items = dict_processor.process()

    sorting_engine = SortingEngine()
    sorted_order_items = sorting_engine.sort_items(processed_items)

    output_formatter = OutputFormatter()
    final_output = output_formatter.format_output(sorted_order_items)

    return final_output

