    def process_data(self, data_list):
        return sorted(data_list)

class ListSorter:
    def sort_elements(self, elements):
        return sorted(elements)

class MedianCalculator:
    def calculate(self, sorted_numbers):
        list_length = len(sorted_numbers)
        middle_index = list_length // 2
        if list_length % 2 == 1:
            return sorted_numbers[middle_index]
        else:
            return (sorted_numbers[middle_index - 1] + sorted_numbers[middle_index]) / 2.0

class InputValidator:
    def is_valid_input(self, numbers):
        return isinstance(numbers, list) and all(isinstance(n, (int, float)) for n in numbers)

class ResultFormatter:
    def format_output(self, value):
        return value

def calculate_median(numbers):
    input_validator = InputValidator()
    if not input_validator.is_valid_input(numbers):
        raise ValueError("Input must be a list of numbers.")

    list_sorter = ListSorter()
    sorted_numbers = list_sorter.sort_elements(numbers)

    median_calculator = MedianCalculator()
    median_value = median_calculator.calculate(sorted_numbers)

    result_formatter = ResultFormatter()
    return result_formatter.format_output(median_value)

