        return base ** exponent

class SumAggregator:
    def aggregate_sum(self, numbers):
        return sum(numbers)

class ArmstrongNumberChecker:
    def check_number(self, original_number, calculated_sum):
        return original_number == calculated_sum

def is_armstrong(number):
    number_as_string_data = DigitExtractor(number)
    digits = number_as_string_data.extract_digits()
    count_data = DigitCount(digits)
    num_digits = count_data.get_count()
    power_op = PowerCalculator()
    powered_digits = [power_op.calculate_power(d, num_digits) for d in digits]
    sum_op = SumAggregator()
    calculated_sum = sum_op.aggregate_sum(powered_digits)
    checker = ArmstrongNumberChecker()
    return checker.check_number(number, calculated_sum)

