class TemperatureUnit:
    def __init__(self, name):
        self.unitName = name

class TemperatureConverter:
    def __init__(self):
        self.conversionFactor = 5/9

class ConversionOffset:
    def __init__(self, offset):
        self.offsetValue = offset

class OutputPrecision:
    def __init__(self, decimal_places):
        self.roundTo = decimal_places

class TemperatureMeasurement:
    def __init__(self, value, unit):
        self.temperatureValue = value
        self.temperatureUnit = unit

def fahrenheit_to_celsius(fahrenheit_value):
    fahrenheit_unit = TemperatureUnit("Fahrenheit")
    celsius_unit = TemperatureUnit("Celsius")
    input_measurement = TemperatureMeasurement(fahrenheit_value, fahrenheit_unit)

    converter_instance = TemperatureConverter()
    offset_instance = ConversionOffset(32)
    precision_instance = OutputPrecision(1)

    intermediate_value = input_measurement.temperatureValue - offset_instance.offsetValue
    celsius_raw = intermediate_value * converter_instance.conversionFactor

    return round(celsius_raw, precision_instance.roundTo)

