        self.itemValue = value

class WeightFactor:
    def __init__(self, factor):
        self.weightFactor = factor

class CalculationResult:
    def __init__(self, result):
        self.finalResult = result

class SumAggregator:
    def __init__(self):
        self.totalSum = 0.0

    def add_to_sum(self, value):
        self.totalSum += value

class AverageCalculator:
    def calculate_average(self, total_sum, total_weight):
        if total_weight == 0:
            return CalculationResult(0.0)
        return CalculationResult(total_sum / total_weight)

def weighted_average(values, weights):
    product_sum_aggregator = SumAggregator()
    total_weight_aggregator = SumAggregator()

    for i in range(len(values)):
        current_value_item = ValueItem(values[i])
        current_weight_factor = WeightFactor(weights[i])
        product_sum_aggregator.add_to_sum(current_value_item.itemValue * current_weight_factor.weightFactor)
        total_weight_aggregator.add_to_sum(current_weight_factor.weightFactor)

    avg_calculator = AverageCalculator()
    final_average = avg_calculator.calculate_average(product_sum_aggregator.totalSum, total_weight_aggregator.totalSum)
    return final_average.finalResult

