import collections

class CharCounter:
    def __init__(self, input_string):
        self.char_counts = collections.Counter(input_string)

class FrequencyFinder:
    def __init__(self, char_counts_object):
        self.counts = char_counts_object.char_counts

    def get_min_frequency(self):
        return min(self.counts.values())

class CharOccurrence:
    def __init__(self, char, frequency):
        self.character = char
        self.frequency = frequency

class LeastFrequentCharacterIdentifier:
    def __init__(self, text_input):
        self.text_input = text_input

    def find_least_frequent(self):
        char_processor = CharCounter(self.text_input)
        freq_analyzer = FrequencyFinder(char_processor)
        min_freq = freq_analyzer.get_min_frequency()

        for char in self.text_input:
            current_occurrence = CharOccurrence(char, char_processor.char_counts[char])
            if current_occurrence.frequency == min_freq:
                return current_occurrence.character
        return ''

def least_frequent_char(text_string):
    finder_instance = LeastFrequentCharacterIdentifier(text_string)
    return finder_instance.find_least_frequent()

