    accumulator = DecimalAccumulator()
    converter = HexConverter()
    powerCalc = PowerCalculator()
    reverser = StringReverser()

    reversed_hex = reverser.reverse(hex_string)

    for index, hex_char in enumerate(reversed_hex):
        decimal_digit = converter.convertHexChar(hex_char)
        positional_value = powerCalc.calculatePower(16, index)
