import datetime

class DateConverter:
    def __init__(self, date_string):
        self.date_string = date_string

    def to_datetime_object(self):
        return datetime.datetime.strptime(self.date_string, '%Y-%m-%d')

class DateDifferenceCalculator:
    def calculate(self, start_date_obj, end_date_obj):
        time_delta = end_date_obj - start_date_obj
        return time_delta.days

class DateInputValidator:
    def is_valid_format(self, date_string):
        try:
            datetime.datetime.strptime(date_string, '%Y-%m-%d')
            return True
        except ValueError:
            return False

class DateProcessor:
    def process_dates(self, start_str, end_str):
        start_converter = DateConverter(start_str)
        end_converter = DateConverter(end_str)
        start_datetime = start_converter.to_datetime_object()
        end_datetime = end_converter.to_datetime_object()
        calculator = DateDifferenceCalculator()
        return calculator.calculate(start_datetime, end_datetime)

class MainApplication:
    def days_between_dates(self, start_date_str, end_date_str):
        processor = DateProcessor()
        validator = DateInputValidator()
        if not validator.is_valid_format(start_date_str) or not validator.is_valid_format(end_date_str):
            raise ValueError("Invalid date format. Expected YYYY-MM-DD.")
        return processor.process_dates(start_date_str, end_date_str)

def days_between_dates(start_date_str, end_date_str):
    app_instance = MainApplication()
    return app_instance.days_between_dates(start_date_str, end_date_str)

