    def __init__(self):
        self.resultantList = []

def fibonacci_sequence(limitValue: int) -> list[int]:
    sequenceBuilder = SequenceGenerator()
    processor = NumberProcessor()
    fibSeries = FibonacciSeries()
    outputContainer = OutputList()

    if limitValue <= fibSeries.firstValue:
        return outputContainer.resultantList

    outputContainer.resultantList.append(processor.processNumber(fibSeries.firstValue))
    if limitValue == fibSeries.secondValue:
        return outputContainer.resultantList

    outputContainer.resultantList.append(processor.processNumber(fibSeries.secondValue))

    state = CurrentState(fibSeries.firstValue, fibSeries.secondValue)

    while True:
        nextNumber = state.previousNumber + state.currentNumber
        if nextNumber >= limitValue:
            break
        outputContainer.resultantList.append(processor.processNumber(nextNumber))
        state.previousNumber = state.currentNumber
        state.currentNumber = nextNumber

    return outputContainer.resultantList

