        if productValue == 0.0 and len(numberElements) == 0:
            return 0.0
        if productValue == 0.0:
            return 0.0

        return RootFinder().findNthRoot(productValue, len(numberElements))

def geometric_mean(numbers):
    numberCollection = NumberList(numbers)
    meanProcessor = GeometricMeanProcessor()
    return meanProcessor.calculate(numberCollection.valueElements)

