    def calculate_factorial(self, n):
        if n < 0:
            raise ValueError("Input must be a non-negative integer.")
        if n == 0:
            return 1

        current_product = 1
        for i in range(1, n + 1):
            current_product *= i

        final_result = current_product 
        return final_result

