class NumberParser:
    def parse(self, part):
        return int(part)

class OperatorExtractor:
    def extract(self, expression_string):
        if '+' in expression_string:
            return '+'
        elif '-' in expression_string:
            return '-'
        return None

class OperandSplitter:
    def split(self, expression_string, operator_symbol):
        return expression_string.split(operator_symbol)

class CalculationPerformer:
    def perform_addition(self, num1, num2):
        return num1 + num2

    def perform_subtraction(self, num1, num2):
        return num1 - num2

class ExpressionEvaluator:
    def evaluate(self, operand_one, operand_two, operation_type):
        calculation_engine = CalculationPerformer()
        if operation_type == '+':
            return calculation_engine.perform_addition(operand_one, operand_two)
        elif operation_type == '-':
            return calculation_engine.perform_subtraction(operand_one, operand_two)
        raise ValueError("Unsupported operation")

class ResultFormatter:
    def format_integer(self, value):
        return int(value)

class InputValidator:
    def validate_expression(self, expr):
        if not isinstance(expr, str) or not expr:
            raise ValueError("Expression must be a non-empty string.")

def simple_calculator(expression_input):
    validator_instance = InputValidator()
    validator_instance.validate_expression(expression_input)

    operator_finder = OperatorExtractor()
    detected_operator = operator_finder.extract(expression_input)
    if not detected_operator:
        raise ValueError("No valid operator found.")

    parts_splitter = OperandSplitter()
    operand_parts = parts_splitter.split(expression_input, detected_operator)
    if len(operand_parts) != 2:
        raise ValueError("Invalid expression format.")

    value_parser = NumberParser()
    first_number = value_parser.parse(operand_parts[0])
    second_number = value_parser.parse(operand_parts[1])

    evaluation_service = ExpressionEvaluator()
    calculated_result = evaluation_service.evaluate(first_number, second_number, detected_operator)

    output_formatter = ResultFormatter()
    return output_formatter.format_integer(calculated_result)

