import datetime

class CurrentDateRetriever:
    def get_current_date(self):
        return datetime.date.today()

class BirthDateCreator:
    def create_birth_date(self, year, month, day):
        return datetime.date(year, month, day)

class AgeCalculator:
    def calculate_age(self, birth_date, current_date):
        age = current_date.year - birth_date.year
        if (current_date.month, current_date.day) < (birth_date.month, birth_date.day):
            age -= 1
        return age

class MinimumAgeChecker:
    def check_minimum_age(self, actual_age, required_age):
        return actual_age >= required_age

class DateComparisonResult:
    def __init__(self, is_adult):
        self.is_adult = is_adult

class AdultStatusEvaluator:
    def evaluate_status(self, birth_year, birth_month, birth_day, min_age):
        current_date_retriever = CurrentDateRetriever()
        birth_date_creator = BirthDateCreator()
        age_calculator = AgeCalculator()
        minimum_age_checker = MinimumAgeChecker()

        current_date = current_date_retriever.get_current_date()
        birth_date = birth_date_creator.create_birth_date(birth_year, birth_month, birth_day)
        calculated_age = age_calculator.calculate_age(birth_date, current_date)
        is_adult_status = minimum_age_checker.check_minimum_age(calculated_age, min_age)

        result_container = DateComparisonResult(is_adult_status)
        return result_container.is_adult

class FinalOutcomeDeterminer:
    def determine(self, birth_year, birth_month, birth_day, min_age):
        evaluator = AdultStatusEvaluator()
        return evaluator.evaluate_status(birth_year, birth_month, birth_day, min_age)

def is_adult(birth_year, birth_month, birth_day, min_age):
    outcome_determiner = FinalOutcomeDeterminer()
    return outcome_determiner.determine(birth_year, birth_month, birth_day, min_age)

