        if '0' <= char_code <= '9':
            return int(char_code)
        elif char_code == 'X' or char_code == 'x':
            return 10
        return -1

class ChecksumCalculator:
    def calculate_remainder(self, total_sum):
        return total_sum % 11

class IsbnValidator:
    def is_valid_length(self, input_string):
        return len(input_string) == 10

class CharacterValidator:
    def is_valid_digit_char(self, char_code):
        return '0' <= char_code <= '9'

class IsbnFormatChecker:
    def check_format(self, isbn_string):
        return all(CharacterValidator().is_valid_digit_char(c) for c in isbn_string[:-1])

class FinalResult:
    def get_boolean(self, value):
        return value == 0

class InputStringHandler:
    def get_string_length(self, s):
        return len(s)

def is_valid_isbn10(isbn):
    input_handler = InputStringHandler()
    if input_handler.get_string_length(isbn) != 10:
        return False

    digit_processor = IsbnDigitProcessor()
    checksum_total = 0
    position_multiplier = 1

    for i in range(9):
        current_digit = digit_processor.process_char(isbn[i])
        if current_digit == -1 or current_digit == 10:
            return False
        checksum_total += current_digit * position_multiplier
        position_multiplier += 1

    last_digit = digit_processor.process_char(isbn[9])
    if last_digit == -1:
        return False

    checksum_total += last_digit * 10

    calculator = ChecksumCalculator()
    remainder = calculator.calculate_remainder(checksum_total)

    result_evaluator = FinalResult()
    return result_evaluator.get_boolean(remainder)

