class LineBuilder:
    def __init__(self, max_width_param):
        self.current_line_words = []
        self.current_line_length = 0
        self.maximum_width = max_width_param

    def add_word(self, word_entry):
        if not self.current_line_words:
            new_length = len(word_entry)
        else:
            new_length = self.current_line_length + 1 + len(word_entry)

        if new_length <= self.maximum_width:
            self.current_line_words.append(word_entry)
            self.current_line_length = new_length
            return True
        return False

    def get_formatted_line(self):
        return " ".join(self.current_line_words)

class WordProcessor:
    def __init__(self, initial_words):
        self.word_sequence = initial_words

    def get_next_word(self):
        if self.word_sequence:
            return self.word_sequence.pop(0)
        return None

class JustificationEngine:
    def __init__(self, width_setting):
        self.line_max_width = width_setting
        self.output_lines = []

    def process_words(self, words_to_process):
        word_source = WordProcessor(list(words_to_process))
        current_word = word_source.get_next_word()

        while current_word is not None:
            line_composer = LineBuilder(self.line_max_width)
            successful_add = line_composer.add_word(current_word)

            if not successful_add:
                # Should not happen given problem constraints (single word fits)
                pass

            next_word_candidate = word_source.get_next_word()
            while next_word_candidate is not None:
                if line_composer.add_word(next_word_candidate):
                    next_word_candidate = word_source.get_next_word()
                else:
                    self.output_lines.append(line_composer.get_formatted_line())
                    current_word = next_word_candidate
                    break
            else:
                self.output_lines.append(line_composer.get_formatted_line())
                current_word = None
        return self.output_lines

class TextFormatter:
    def __init__(self):
        pass

    def join_lines(self, lines_list):
        return "\n".join(lines_list)

class InputValidator:
    def __init__(self):
        pass

    def validate_input(self, words_list, width_val):
        if not isinstance(words_list, list) or not all(isinstance(w, str) for w in words_list):
            raise TypeError("Words must be a list of strings.")
        if not isinstance(width_val, int) or width_val <= 0:
            raise ValueError("Max width must be a positive integer.")

def justify_text_simple(words, max_width):
    input_checker = InputValidator()
    input_checker.validate_input(words, max_width)

    formatting_process = JustificationEngine(max_width)
    result_lines = formatting_process.process_words(words)

    final_output_producer = TextFormatter()
    return final_output_producer.join_lines(result_lines)

