class PointCoordinate:
    def __init__(self, value):
        self.value = value

class CartesianPoint:
    def __init__(self, x_coordinate, y_coordinate):
        self.x_coordinate = x_coordinate
        self.y_coordinate = y_coordinate

class QuadrantClassifier:
    def determine_quadrant(self, x_input, y_input):
        current_point = CartesianPoint(PointCoordinate(x_input), PointCoordinate(y_input))
        x_val = current_point.x_coordinate.value
        y_val = current_point.y_coordinate.value

        if x_val == 0 or y_val == 0:
            return 0
        elif x_val > 0 and y_val > 0:
            return 1
        elif x_val < 0 and y_val > 0:
            return 2
        elif x_val < 0 and y_val < 0:
            return 3
        else:
            return 4

class QuadrantResult:
    def __init__(self, result_value):
        self.result_value = result_value

class SolutionProcessor:
    def process_coordinates(self, x_data, y_data):
        classifier_instance = QuadrantClassifier()
        final_quadrant = classifier_instance.determine_quadrant(x_data, y_data)
        return QuadrantResult(final_quadrant).result_value

class InputProcessor:
    def get_quadrant(self, x_value, y_value):
        processor = SolutionProcessor()
        return processor.process_coordinates(x_value, y_value)

class EntryPoint:
    def execute(self, x, y):
        main_processor = InputProcessor()
        return main_processor.get_quadrant(x, y)

def get_quadrant(x, y):
    program_runner = EntryPoint()
    return program_runner.execute(x, y)

