class NumberListProcessor:
    def __init__(self, data_list):
        self.original_data = list(data_list)

class SortedListHolder:
    def __init__(self, sorted_numbers):
        self.sorted_values = sorted_numbers

class ListLengthAnalyzer:
    def __init__(self, length):
        self.item_count = length

class MedianValue:
    def __init__(self, value):
        self.result_value = value

class MiddleIndexCalculator:
    def __init__(self, length):
        self.mid_point = length // 2

class EvenLengthProcessor:
    def __init__(self, val1, val2):
        self.first_middle = val1
        self.second_middle = val2

class OddLengthProcessor:
    def __init__(self, val):
        self.single_middle = val

def calculate_median(number_list):
    input_processor = NumberListProcessor(number_list)
    if not input_processor.original_data:
        return None

    sorted_numbers = sorted(input_processor.original_data)
    sorted_holder = SortedListHolder(sorted_numbers)
    list_analyzer = ListLengthAnalyzer(len(sorted_holder.sorted_values))
    mid_calc = MiddleIndexCalculator(list_analyzer.item_count)

    if list_analyzer.item_count % 2 == 1:
        odd_processor = OddLengthProcessor(sorted_holder.sorted_values[mid_calc.mid_point])
        final_median = MedianValue(odd_processor.single_middle)
        return final_median.result_value
    else:
        even_processor = EvenLengthProcessor(
            sorted_holder.sorted_values[mid_calc.mid_point - 1],
            sorted_holder.sorted_values[mid_calc.mid_point]
        )
        final_median = MedianValue((even_processor.first_middle + even_processor.second_middle) / 2)
        return final_median.result_value

