import math

class PointCoordinate:
    def __init__(self, x_value, y_value):
        self.x_value = x_value
        self.y_value = y_value

class CircleCenter:
    def __init__(self, x_coordinate, y_coordinate):
        self.x_coordinate = x_coordinate
        self.y_coordinate = y_coordinate

class CircleRadius:
    def __init__(self, radius_value):
        self.radius_value = radius_value

class DistanceCalculator:
    def calculate_distance(self, point_one, point_two):
        dx = point_one.x_value - point_two.x_coordinate
        dy = point_one.y_value - point_two.y_coordinate
        return math.sqrt(dx*dx + dy*dy)

class ComparisonResult:
    def __init__(self, is_inside):
        self.is_inside = is_inside

class BoundaryCheck:
    def check_boundary(self, calculated_distance, circle_radius):
        return calculated_distance <= circle_radius.radius_value

class CircleEvaluator:
    def evaluate(self, point_object, center_object, radius_object):
        distance_engine = DistanceCalculator()
        current_distance = distance_engine.calculate_distance(point_object, center_object)
        boundary_check_engine = BoundaryCheck()
        final_result = boundary_check_engine.check_boundary(current_distance, radius_object)
        return ComparisonResult(final_result).is_inside

def is_point_in_circle(px, py, cx, cy, radius):
    point_instance = PointCoordinate(px, py)
    center_instance = CircleCenter(cx, cy)
    radius_instance = CircleRadius(radius)
    evaluation_processor = CircleEvaluator()
    return evaluation_processor.evaluate(point_instance, center_instance, radius_instance)

