from datetime import date, timedelta

class DateIterator:
    def __init__(self, start_date, end_date):
        self.current_date = start_date
        self.end_date = end_date

    def __iter__(self):
        return self

    def __next__(self):
        if self.current_date > self.end_date:
            raise StopIteration
        return_date = self.current_date
        self.current_date += timedelta(days=1)
        return return_date

class DateRangeCreator:
    def create_range(self, start_date, end_date):
        return DateIterator(start_date, end_date)

class MonthBoundaryCalculator:
    def get_start_date(self, year_value, month_value):
        return date(year_value, month_value, 1)

    def get_end_date(self, year_value, month_value):
        if month_value == 12:
            return date(year_value, 12, 31)
        return date(year_value, month_value + 1, 1) - timedelta(days=1)

class WeekdayChecker:
    def is_business_day(self, current_date):
        return 0 <= current_date.weekday() <= 4

class BusinessDayCounter:
    def count_days(self, date_range, weekday_checker):
        business_day_count = 0
        for current_day in date_range:
            if weekday_checker.is_business_day(current_day):
                business_day_count += 1
        return business_day_count

