    daily_date_range = date_range_creator.create_range(first_day_of_month, last_day_of_month)

    weekday_evaluator = WeekdayChecker()
    business_day_accumulator = BusinessDayCounter()

    return business_day_accumulator.count_days(daily_date_range, weekday_evaluator)

