                self.name_text = name_text

            def split_into_words(self):
                return [word for word in self.name_text.strip().split(' ') if word]

        if not self.full_name_string:
            return ""

        splitter = NameSplitter(self.full_name_string)
        parts = splitter.split_into_words()

        if not parts:
