class QueryStringProcessor:
    def __init__(self, url_input_string):
        self.url_input_string = url_input_string

    def extract_query_string(self):
        query_start_position = self.url_input_string.find('?')
        if query_start_position == -1:
            return ""
        return self.url_input_string[query_start_position + 1:]

class ParamStringSplitter:
    def __init__(self, raw_query_string):
        self.raw_query_string = raw_query_string

    def split_into_param_pairs(self):
        if not self.raw_query_string:
            return []
        return self.raw_query_string.split('&')

class KeyValuePairParser:
    def parse_pair(self, param_pair_string):
        parts = param_pair_string.split('=', 1)
        if len(parts) == 2:
            return parts[0], parts[1]
        return None, None

class ParamCollectionBuilder:
    def __init__(self):
        self.param_dictionary = {}

    def add_parameter(self, key_string, value_string):
        if key_string is not None and value_string is not None:
            self.param_dictionary[key_string] = value_string

    def get_final_parameters(self):
        return self.param_dictionary

class URLParameterExtractor:
    def extract_from_url(self, url_string):
        string_processor = QueryStringProcessor(url_string)
        query_data_string = string_processor.extract_query_string()

        pair_splitter = ParamStringSplitter(query_data_string)
        parameter_pairs = pair_splitter.split_into_param_pairs()

        dictionary_builder = ParamCollectionBuilder()
        for single_pair in parameter_pairs:
            pair_parser = KeyValuePairParser()
            key_identifier, value_content = pair_parser.parse_pair(single_pair)
            dictionary_builder.add_parameter(key_identifier, value_content)
        return dictionary_builder.get_final_parameters()

def parse_url_params(url_string_value):
    param_extractor = URLParameterExtractor()
    return param_extractor.extract_from_url(url_string_value)

